import{_ as r,l as t,o as e,c as l,v as n,p as s,x as i,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"Scheinkman–Xiong 换手与泡沫","description":"","frontmatter":{"title":"Scheinkman–Xiong 换手与泡沫","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/scheinkman-xiong.md","filePath":"econ/scheinkman-xiong.md","lastUpdated":1789023840000}'),h={name:"econ/scheinkman-xiong.md"};function E(m,a,B,_,A,u){const o=t("Mermaid");return e(),l("div",null,[a[1]||(a[1]=n('<h1 id="scheinkman–xiong-换手与泡沫" tabindex="-1">Scheinkman–Xiong 换手与泡沫 <a class="header-anchor" href="#scheinkman–xiong-换手与泡沫" aria-label="Permalink to &quot;Scheinkman–Xiong 换手与泡沫&quot;">​</a></h1><div class="epigraph"><p>过度自信让人不断以为自己比别人准，于是不停地换手；泡沫的体积和成交量是同一枚转售期权的两面。</p><footer>—— Scheinkman and Xiong, Overconfidence and Speculative Bubbles, Journal of Political Economy, 2003</footer></div><p><a href="/econ/harrison-kreps-speculation">上一课</a>给出转售期权。本课缺口是把期权的燃料写成<a href="/econ/overconfidence">过度自信</a>：连续时间里两组人各自高估私有信号，信念持续分歧，换手与泡沫同时出现。不重导 Harrison–Kreps 的离散期权。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Harrison–Kreps 的信念异质可以是外生的。Scheinkman 与 Xiong（2003）让异质来自过度精确：两组观察带噪声的同一基本面，每组低估自己的噪声、相对高估对方的噪声，后验不收敛。禁止卖空。当前持有者总把资产标上「卖给另一组」的期权，价格 = 基本面（在自己信念下）+ 期权。成交在两组轮流成为更乐观者时发生。缺口是同时解释<strong>泡沫与换手</strong>，而不是只解释价格水平。</p><p><span class="marginnote">共同先验下，仅有不同信息通常会通过价格学习而收敛。过度自信切断这条学习：人把价格里对方的信息当成更噪。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>连续时间滤波，两组过度自信，卖空约束，风险中性或近似。资产价格有闭式期权解释。比较静态：过度自信越强，期权越贵，换手越高，波动越大。与 DHS 的差别：DHS 强调动量与反转的时间序列；SX 强调成交量与泡沫共存。</p>',8)),(e(),s(d,null,{default:i(()=>[p(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20HK%5B%22Harrison-Kreps%3A%20%E8%BD%AC%E5%94%AE%E6%9C%9F%E6%9D%83%22%5D%20--%3E%20OC%5B%22%E8%BF%87%E5%BA%A6%E7%B2%BE%E7%A1%AE%3A%20%E5%88%86%E6%AD%A7%E4%B8%8D%E6%94%B6%E6%95%9B%22%5D%0A%20%20OC%20--%3E%20BUB%5B%22%E4%BB%B7%E6%A0%BC%20%3D%20%E5%9F%BA%E6%9C%AC%E9%9D%A2%20%2B%20%E6%9C%9F%E6%9D%83%22%5D%0A%20%20OC%20--%3E%20TO%5B%22%E6%8D%A2%E6%89%8B%3A%20%E4%B9%90%E8%A7%82%E8%80%85%E8%BA%AB%E4%BB%BD%E8%BD%AE%E6%8D%A2%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<p>本课仍不进入簿的撮合。换手是持有权在两组间转移，不是队列几何。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是信念的持续错位。每组的卡尔曼增益太大，把对方推动的价格变动当成噪声，不充分更新。卖空限制阻止悲观仓位，期权保持正值。价格可以长期高于「正确滤波」的基本面，同时成交活跃——这与「没有成交的死泡沫」不同，也与理性泡沫（下一课）的低换手潜在对照。</p><p>套利限制仍在：若允许卖空并有无限资本，期权被压掉。SX 把 SV 的融资摩擦当成背景，焦点在信念。</p><p>共同先验加正确滤波，两组后验应收敛，转售期权趋于零。过度精确切断学习：对方推动的价格被当成噪声，分歧是稳态。卖空一关，悲观组无法把负仓拿满，期权保持正。换手是「谁更乐观」的轮换频率，不是噪声交易者的随机需求。与 DHS 的时间序列故事分工：这里强调成交量与泡沫水平同时高。仍不写簿上的撮合。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>两组是简化；多组、连续异质更接近现场，定性类似。风险厌恶会削弱期权价值。基本面若可完全合同化，投机动机下降。本课不把 1990 年代科技股的换手当成证明，只给可对照的符号：泡沫期换手应高。</p><p>后课默认：理性泡沫可以在共同信念下存在，不需要过度自信，但通常对换手沉默。</p><p>过度精确让分歧不收敛，转售期权保持正值；乐观者身份轮换同时给出换手。</p><p>泡沫体积与成交量是同一机制。理性泡沫下一课对换手沉默，形成对照。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>过度自信维持分歧，转售期权给出泡沫，轮换给出换手。</li><li>价格与成交量是同一机制，不是两则轶事。</li><li>卖空限制仍是必要约束。</li><li>对方推动的价格被当成噪声，学习被切断。</li><li>允许卖空并有无限资本则期权被压掉。</li><li>出处：Scheinkman and Xiong, <em>JPE</em> 2003。</li></ul>',12))])}const S=r(h,[["render",E]]);export{k as __pageData,S as default};
